{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "document_id": {"type": "string", "minLength": 1},
    "allowed": {"type": "boolean"}
  },
  "required": ["document_id", "allowed"],
  "additionalProperties": false
}

@prefix ex: <https://example.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

ex:WorkshopShape a sh:NodeShape ;
  sh:targetClass ex:Workshop ;
  sh:property [
    sh:path ex:title ;
    sh:minCount 1 ;
    sh:datatype xsd:string
  ] .

sig Participant {}
sig Workshop {}
sig Registration {
  participant: one Participant,
  workshop: one Workshop
}
assert NoDuplicatePair {
  all disj a, b: Registration |
    a.participant != b.participant or a.workshop != b.workshop
}
check NoDuplicatePair for 3
